```python
import copy
import unittest
from thread_delta import compare


def fixture():
    return {"post": {"id": "root", "body": "Hello", "score": 0},
            "items": [], "next_before": None}


class DeltaTests(unittest.TestCase):
    def test_unchanged(self):
        result = compare(fixture(), fixture())
        self.assertEqual(result["newly_observed"], [])
        self.assertEqual(result["changed"], [])

    def test_added_and_changed(self):
        old = fixture()
        new = copy.deepcopy(old)
        new["items"] = [{"id": "reply", "body": "Hello back"}]
        new["post"].update(body="Edited", score=1)
        result = compare(old, new)
        self.assertEqual(result["newly_observed"][0]["id"], "reply")
        self.assertEqual(set(result["changed"][0]["fields"]), {"body", "score"})

    def test_missing_partial_is_not_deletion(self):
        old = fixture()
        old["items"] = [{"id": "older", "body": "Previous page"}]
        new = fixture()
        new["next_before"] = 10
        result = compare(old, new)
        self.assertFalse(result["coverage"]["new_reached_tail"])
        self.assertEqual(result["not_observed_in_new_snapshot"], ["older"])
        self.assertNotIn("deleted", result)

    def test_null_is_not_zero(self):
        old, new = fixture(), fixture()
        new["post"]["score"] = None
        result = compare(old, new)
        self.assertIsNone(result["changed"][0]["fields"]["score"]["after"])

    def test_mismatched_roots(self):
        old, new = fixture(), fixture()
        new["post"]["id"] = "another"
        with self.assertRaises(ValueError):
            compare(old, new)

    def test_duplicate_ids(self):
        new = fixture()
        new["items"] = [new["post"]]
        with self.assertRaises(ValueError):
            compare(fixture(), new)

    def test_missing_body(self):
        new = fixture()
        del new["post"]["body"]
        with self.assertRaises(ValueError):
            compare(fixture(), new)


if __name__ == "__main__":
    unittest.main()

```
